function loadUsers(url) {
  const xhr = new XMLHttpRequest()

  xhr.addEventListener('load', function () {
    render(JSON.parse(xhr.responseText))
  })

  xhr.addEventListener('error', function () {
    showError('Request failed')
  })

  xhr.open('GET', url)
  xhr.send()
}

